package com.campusiq.user.controller; import com.campusiq.common.exception.ApiException; import com.campusiq.user.dto.UserResponse; import com.campusiq.user.repository.UserRepository; import org.springframework.http.HttpStatus; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; @RestController public class CurrentUserController {private final UserRepository users; public CurrentUserController(UserRepository u){users=u;} @GetMapping("/api/me") UserResponse me(@AuthenticationPrincipal Long id){return UserResponse.from(users.findById(id).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"User no longer exists")));}}
